    /// must match and an unsupported one must not.
    #[test]
    #[cfg(feature = "schemars")]
    fn test_supported_file_ext_pattern_covers_all_extension_map_entries() {
        let pattern = crate::schema_helpers::supported_file_ext_pattern();
